  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    memory = []
    for i, trial in enumerate(trials):
        new_entry = {
            'last_trial': i,
            'reflection': trial['reflection'],
            'signature': trial['signature'],
            'success': trial['success']
        }
        if not trial['success']:
            # deduplicate failure signatures, keep newest
            found = None
            for j, entry in enumerate(memory):
                if entry['signature'] == trial['signature'] and not entry['success']:
                    found = j
                    break
            if found is not None:
                memory.pop(found)
        memory.append(new_entry)
        # prune to capacity
        if len(memory) > capacity:
            # sort by priority: failures first, then recency descending, then signature
            memory.sort(key=lambda e: (1 if e['success'] else 0, -e['last_trial'], e['signature']))
            memory = memory[:capacity]
            # restore chronological order
            memory.sort(key=lambda e: e['last_trial'])
    signatures = [e['signature'] for e in memory]
    return {'memory': memory, 'signatures': signatures}"
}
